      gradient.addColorStop(0.27885, 'rgb(252 237 153 / 23%)');
      gradient.addColorStop(0.63462, 'rgb(255 215 176 / 23%)');
      gradient.addColorStop(1, 'rgb(249 177 179 / 23%)');
